import{_ as r,c as t,o as a,ag as o}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Matrix Migrating Servers","description":"","frontmatter":{"title":"Matrix Migrating Servers"},"headers":[],"relativePath":"matrix/matrix-migrating-servers.md","filePath":"matrix/matrix-migrating-servers.md","lastUpdated":null}'),i={name:"matrix/matrix-migrating-servers.md"};function s(n,e,d,c,l,m){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="matrix-migrating-servers" tabindex="-1">Matrix Migrating Servers <a class="header-anchor" href="#matrix-migrating-servers" aria-label="Permalink to &quot;Matrix Migrating Servers&quot;">​</a></h1><p><a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/450e96526c9d31605ff57c63a74cfa6599d03ad3/docs/maintenance-migrating.md?plain=1" target="_blank" rel="noreferrer">https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/450e96526c9d31605ff57c63a74cfa6599d03ad3/docs/maintenance-migrating.md?plain=1</a></p><blockquote><p><strong>Note</strong>: This migration guide is applicable if you migrate from one server to another server having the same CPU architecture (e.g. both servers being <code>amd64</code>).</p></blockquote><p>If you&#39;re trying to migrate between different architectures (e.g. <code>amd64</code> → <code>arm64</code>), simply copying the complete <code>/matrix</code> directory is not possible as it would move the raw PostgreSQL data between different architectures. In this specific case, you can use the guide below as a reference, but you would also need to dump the database on your current server and import it properly on the new server. See our PostgreSQL backup docs for help with PostgreSQL backup/restore.</p><h2 id="migrating-to-new-server" tabindex="-1">Migrating to new server <a class="header-anchor" href="#migrating-to-new-server" aria-label="Permalink to &quot;Migrating to new server&quot;">​</a></h2><ol><li>Prepare by lowering DNS TTL for your domains (<code>matrix.DOMAIN</code>, etc.), so that DNS record changes (step 4 below) would happen faster, leading to less downtime</li><li>Stop all services on the old server and make sure they won&#39;t be starting again. Execute this on the old server: <code>systemctl disable --now matrix*</code> (you might have to cd to /etc/systemd/system/ first)</li><li>Copy directory <code>/matrix</code> from the old server to the new server. Make sure to preserve ownership and permissions (use <code>cp -p</code> or <code>rsync -ar</code>)!</li><li>Make sure your DNS records are adjusted to point to the new server&#39;s IP address</li><li>Remove old server from the <code>inventory/hosts</code> file and add new server.</li><li>Run <code>ansible-playbook -i inventory/hosts setup.yml --tags=setup-system-user</code>. This will create the <code>matrix</code> user and group on the new server</li><li>Because the <code>matrix</code> user and group are created dynamically on each server, the user/group id may differ between the old and new server. We suggest that you adjust ownership of <code>/matrix</code> files manually by running this on the new server: <code>chown -R matrix:matrix /matrix</code>.</li><li>Run <code>ansible-playbook -i inventory/hosts setup.yml --tags=setup-all,start</code> to finish the installation and start all services</li></ol>',6)])])}const p=r(i,[["render",s]]);export{h as __pageData,p as default};
